previewCss:
.darma-loader-darma-b13-water-wheel { --accent: var(--loader-color, #a16207); --accent-2: var(--loader-secondary-color, #0ea5e9); width: var(--loader-size, 104px); height: var(--loader-size, 104px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b13-water-wheel::after { content: ''; position: absolute; bottom: 4%; left: 0; width: 100%; height: 15%; border-radius: 4px; background: linear-gradient(90deg, var(--accent-2) 0 50%, color-mix(in srgb, #fff 42%, var(--accent-2)) 50% 100%); background-size: calc(var(--loader-size, 104px) * .24) 100%; animation: darma-loader-darma-b13-water-wheel-current calc(var(--loader-speed, 1s) * 1.2) linear infinite; }
.darma-loader-darma-b13-water-wheel .darma-loader-darma-b13-water-wheel__wheel { position: relative; width: 66%; height: 66%; border-radius: 50%; box-shadow: 0 0 0 calc(var(--loader-size, 104px) * .035) var(--accent); animation: darma-loader-darma-b13-water-wheel-churn calc(var(--loader-speed, 1s) * 3) linear infinite; }
.darma-loader-darma-b13-water-wheel .darma-loader-darma-b13-water-wheel__wheel span { position: absolute; top: 50%; left: 50%; width: 46%; height: 11%; margin-top: -5.5%; border-radius: 2px; transform-origin: left center; background: linear-gradient(90deg, color-mix(in srgb, #000 22%, var(--accent-2)), var(--accent-2)); }
.darma-loader-darma-b13-water-wheel .darma-loader-darma-b13-water-wheel__wheel span:nth-child(2) { transform: rotate(60deg); }
.darma-loader-darma-b13-water-wheel .darma-loader-darma-b13-water-wheel__wheel span:nth-child(3) { transform: rotate(120deg); }
.darma-loader-darma-b13-water-wheel .darma-loader-darma-b13-water-wheel__wheel span:nth-child(4) { transform: rotate(180deg); }
.darma-loader-darma-b13-water-wheel .darma-loader-darma-b13-water-wheel__wheel span:nth-child(5) { transform: rotate(240deg); }
.darma-loader-darma-b13-water-wheel .darma-loader-darma-b13-water-wheel__wheel span:nth-child(6) { transform: rotate(300deg); }
@keyframes darma-loader-darma-b13-water-wheel-churn { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b13-water-wheel-current { to { background-position: calc(var(--loader-size, 104px) * .24) 0; } }

